begin;
create temp table _kba232(node_id integer primary key, blocks jsonb not null, search_text text not null) on commit drop;
insert into _kba232 values (75, $kba232$[{"t":"list","id":"a2-2-3-2-b1","imp":"core","items":["1、==程序设计语言基本三要素：==","==（1）语法：表示构成语言的各个记号之间的组合规律==","==（2）语义：表示程序的各个语法成分含义。语义是程序语言中按语法规则构成的各个语法成分的含义，可分为静态语义和动态语义。==","==（3）语用：程序与使用者之间关系，与运行环境和编译环境有很大关系。==","2、==程序设计语言的四大成分==：","（1）==数据成分==：用来描述程序处理的数据对象（如变量、数组、结构体，即数据名、数据类型、数据结构等）。","（2）==运算成分==：程序中所包括的运算部分（算术运算、逻辑运算、关系运算、算术表达式和逻辑表达式等）。","（3）==控制成分==：表达程序中的控制构造（顺序结构、选择/条件结构、循环结构如 for 等）。","（4）==传输成分==：用来表达程序中数据的传输（数据交换[赋值语句]、拷贝（strcpy、memcpy）、I/O 操作（输入输出库函数调用，如 scanf、printf）、函数传参与返回等）。","3、==高级语言按程序设计方法分类==：","^^面向过程^^：Fortran、C 语言、Pascal、BASIC。","^^面向对象^^：Fortran 2008、VB、Java、C++、C#。","^^数值计算常用语言^^：Fortran、C 语言、MATLAB；==数值计算不等于科学计算==。","4、==传输成分与结构化程序设计==：","^^传输成分^^：==输入用 scanf，输出用 printf==。","^^结构化程序设计^^：是面向过程的程序设计方法，现代程序设计主张使用==顺序、选择、循环三种基本结构==嵌套连接成具有复杂层次的结构化程序，使程序易读、易修改。","5、==计算机的分代与第一台计算机==：","^^世界上第一台计算机 ENIAC^^：诞生于 1946 年，由美国宾夕法尼亚大学研制，用于计算导弹的弹道轨迹（即科学计算）。","^^第一代计算机^^：没有操作系统，使用==机器语言和汇编语言==编写程序。","^^第二代计算机^^：开始使用==高级程序设计语言==。","^^第三代计算机^^：出现==操作系统和数据库管理系统==的概念，目的是为了方便管理计算机资源。","^^第 4 代计算机^^：==大规模和超大规模集成电路计算机==。","6、==C 语言常量与书写风格==：","^^推荐性书写规则^^：==及时书写和修改注释==，注释简明扼要并放在恰当位置；同一层次的语句同列开始，下一层次语句缩进并合理使用花括号；意义相近的语句可写在同一行；同一语句的不同成分之间用空格隔开。复合语句可采用 K&R、Allman、Whitesmiths 或 GNU 缩进风格。","^^整型常量表示^^：可用==八进制（前导 0）、十进制、十六进制（前导 0x）==表示，并可加 u、l、ul 等后缀；八进制每位只能为 0～7，十六进制每位为 0～9、A～F。"],"title":"","ordered":false},{"t":"callout","id":"a2-2-3-2-b2","imp":"core","kind":"tip","text":"任何高级程序设计语言均由四大基本语法成分构成：==数据成分（定义变量与常量类型）、运算成分（算术、关系与逻辑运算符）、控制成分（顺序、分支与循环结构）、传输成分（输入输出与赋值语句）==。","title":"考向复习提示：高级语言语法成分的四要素构成"},{"t":"callout","id":"a2-2-3-2-b3","imp":"core","kind":"trap","text":"==编译程序将高级语言源程序完整翻译，生成独立的目标机器码文件（如 `.obj`/`.exe`）==，之后执行时脱离源程序独立运行，速度极快；而 ==解释程序逐句读取高级语言源代码，边解释边执行，不生成独立的目标代码文件==，每次运行都必须重新翻译；常考单选混淆是否产生目标文件！","title":"高频易错陷阱：编译程序与解释程序的本质区别"}]$kba232$::jsonb, $kba232se$A2-2.3.2 程序设计语言的组成。 1、程序设计语言基本三要素： （1）语法：表示构成语言的各个记号之间的组合规律 （2）语义：表示程序的各个语法成分含义。语义是程序语言中按语法规则构成的各个语法成分的含义，可分为静态语义和动态语义。 （3）语用：程序与使用者之间关系，与运行环境和编译环境有很大关系。 2、程序设计语言的四大成分： （1）数据成分：用来描述程序处理的数据对象（如变量、数组、结构体，即数据名、数据类型、数据结构等）。 （2）运算成分：程序中所包括的运算部分（算术运算、逻辑运算、关系运算、算术表达式和逻辑表达式等）。 （3）控制成分：表达程序中的控制构造（顺序结构、选择/条件结构、循环结构如 for 等）。 （4）传输成分：用来表达程序中数据的传输（数据交换[赋值语句]、拷贝（strcpy、memcpy）、I/O 操作（输入输出库函数调用，如 scanf、printf）、函数传参与返回等）。 3、高级语言按程序设计方法分类： 面向过程：Fortran、C 语言、Pascal、BASIC。 面向对象：Fortran 2008、VB、Java、C++、C#。 数值计算常用语言：Fortran、C 语言、MATLAB；数值计算不等于科学计算。 4、传输成分与结构化程序设计： 传输成分：输入用 scanf，输出用 printf。 结构化程序设计：是面向过程的程序设计方法，现代程序设计主张使用顺序、选择、循环三种基本结构嵌套连接成具有复杂层次的结构化程序，使程序易读、易修改。 5、计算机的分代与第一台计算机： 世界上第一台计算机 ENIAC：诞生于 1946 年，由美国宾夕法尼亚大学研制，用于计算导弹的弹道轨迹（即科学计算）。 第一代计算机：没有操作系统，使用机器语言和汇编语言编写程序。 第二代计算机：开始使用高级程序设计语言。 第三代计算机：出现操作系统和数据库管理系统的概念，目的是为了方便管理计算机资源。 第 4 代计算机：大规模和超大规模集成电路计算机。 6、C 语言常量与书写风格： 推荐性书写规则：及时书写和修改注释，注释简明扼要并放在恰当位置；同一层次的语句同列开始，下一层次语句缩进并合理使用花括号；意义相近的语句可写在同一行；同一语句的不同成分之间用空格隔开。复合语句可采用 K&R、Allman、Whitesmiths 或 GNU 缩进风格。 整型常量表示：可用八进制（前导 0）、十进制、十六进制（前导 0x）表示，并可加 u、l、ul 等后缀；八进制每位只能为 0～7，十六进制每位为 0～9、A～F。 考向复习提示：高级语言语法成分的四要素构成 任何高级程序设计语言均由四大基本语法成分构成：数据成分（定义变量与常量类型）、运算成分（算术、关系与逻辑运算符）、控制成分（顺序、分支与循环结构）、传输成分（输入输出与赋值语句）。 高频易错陷阱：编译程序与解释程序的本质区别 编译程序将高级语言源程序完整翻译，生成独立的目标机器码文件（如 `.obj`/`.exe`），之后执行时脱离源程序独立运行，速度极快；而 解释程序逐句读取高级语言源代码，边解释边执行，不生成独立的目标代码文件，每次运行都必须重新翻译；常考单选混淆是否产生目标文件！$kba232se$);
do $$
declare r record; old_rev record; v_rev integer;
begin
  for r in select node_id, blocks, search_text from _kba232 loop
    select rev_no, html, source_ref into old_rev
      from kb_revision
     where node_id = r.node_id
       and rev_no = (select published_rev from kb_entry where node_id = r.node_id);
    if not found then raise exception 'node % 找不到已发布 revision', r.node_id; end if;
    select coalesce(max(rev_no), 0) + 1 into v_rev from kb_revision where node_id = r.node_id;
    insert into kb_revision(node_id, rev_no, blocks, html, search_text, source_ref)
    values (r.node_id, v_rev, r.blocks, old_rev.html, r.search_text, old_rev.source_ref);
    update kb_entry set published_rev = v_rev, updated_at = now() where node_id = r.node_id;
  end loop;
end $$;
commit;
